"""Offline payload compilation, client replay and origin evidence audit."""
import json
import gc
import math
from pathlib import Path
import re
import sys

# The local no-Docker worker stages the same pinned wheels here. In the public
# image the packages are installed normally and this directory is unnecessary.
if Path('/opt/h3deps').is_dir():
    sys.path.insert(0,'/opt/h3deps')

from schema import compile_cases
from modules.byte_program import Context,MAX
from modules.fuzz_adapter import FuzzExecutor
from modules.capture_audit import audit_channels,TOKEN

NAME = re.compile(r'[A-Za-z0-9_.-]{1,32}\Z',re.ASCII)


def exact(obj,keys):
    if type(obj) is not dict or set(obj)!=set(keys):
        raise ValueError('object keys')


def integer(value,minimum=0,maximum=MAX):
    if type(value) is not int or not minimum <= value <= maximum:
        raise ValueError('integer')
    return value


def sequence(value,maximum):
    if type(value) is not list or len(value)>maximum:
        raise ValueError('array')
    return value


def text(value,maximum=65536):
    if type(value) is not str or len(value)>maximum:
        raise ValueError('string')
    value.encode('utf8')
    return value


def pairs(items):
    out = {}
    for key,value in items:
        if key in out:
            raise ValueError('duplicate key')
        out[key] = value
    return out


def bad_constant(value):
    raise ValueError('nonfinite JSON')


def finite_float(value):
    result = float(value)
    if not math.isfinite(result):
        raise ValueError('nonfinite JSON')
    return result


def compile_document(document):
    exact(document,['seed','definitions','timeout_ms','cases','events','channels'])
    seed = text(document['seed'],64)
    if any(c not in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_.-' for c in seed):
        raise ValueError('seed')
    definitions = sequence(document['definitions'],8192)
    for row in definitions:
        sequence(row,2)
        if len(row)!=2:
            raise ValueError('definition pair')
        text(row[0],32)
        text(row[1],8192)
    context = Context(definitions,seed)
    timeout = integer(document['timeout_ms'],1,10**9)
    cases = sequence(document['cases'],2000)
    names = set()
    budget = 0
    fields_count = 0
    for case in cases:
        exact(case,['name','frames','expect'])
        name = text(case['name'],32)
        if not NAME.fullmatch(name) or name in names:
            raise ValueError('case name')
        names.add(name)
        frames = sequence(case['frames'],50000)
        budget += len(frames)
        pause_total = 0
        for frame in frames:
            if type(frame) is not dict or type(frame.get('Type')) is not str:
                raise ValueError('frame')
            if frame['Type']=='sleep':
                pause_total += integer(frame.get('Time_to_Stop'))
            if frame['Type']=='headers':
                if frame.get('headers_kv') is not None:
                    value = frame['headers_kv']
                    if type(value) is not dict:
                        raise ValueError('header mapping')
                    fields_count += len(value)
                elif frame.get('data_to_transfered') is not None:
                    value = sequence(frame['data_to_transfered'],128)
                    fields_count += len(value)
        if pause_total+timeout > MAX:
            raise ValueError('time overflow')
        exp = case['expect']
        exact(exp,['method','target','host'])
        for k in exp:
            value = text(exp[k],8192).encode('ascii')
            if not value or not all(33 <= c <= 126 for c in value):
                raise ValueError('expected identity')
        if TOKEN.fullmatch(exp['method'].encode('ascii')) is None:
            raise ValueError('expected method')
    payload = compile_cases(cases,context)
    payload_dict = payload.model_dump()
    actual_test_cases = {}
    for case_name,frames in payload_dict['test_cases'].items():
        clean_frames = []
        for frame in frames:
            if 'headers_kv' in frame:
                del frame['headers_kv']
            clean_frames.append(frame)
        actual_test_cases[case_name] = clean_frames
    records = sequence(document['events'],50000)
    budget += len(records)
    events = []
    for index,record in enumerate(records):
        if type(record) is not dict:
            raise ValueError('event')
        kind = record.get('kind')
        keys = ['at','kind'] if kind=='close' else ['at','kind','stream','end',('fields' if kind=='headers' else 'data')]
        exact(record,keys)
        integer(record['at'])
        if kind not in ('close','headers','data'):
            raise ValueError('event kind')
        row = record.copy()
        if kind!='close':
            integer(row['stream'],0,(1 << 32)-1)
            if type(row['end']) is not bool:
                raise ValueError('event end')
        if kind=='headers':
            raw_fields = sequence(row['fields'],128)
            fields_count += len(raw_fields)
            fields = []
            for j,pair in enumerate(raw_fields):
                sequence(pair,2)
                if len(pair)!=2:
                    raise ValueError('event field pair')
                fields.append((context.template(text(pair[0]),f'event/{index}/h/{j}/n'),
                               context.template(text(pair[1]),f'event/{index}/h/{j}/v')))
            row['fields'] = fields
        elif kind=='data':
            row['data'] = context.template(text(row['data']),f'event/{index}/data')
        events.append(row)
    channels = sequence(document['channels'],256)
    channel_names = set()
    compiled_channels = []
    for index,channel in enumerate(channels):
        exact(channel,['name','parts'])
        name = text(channel['name'],32)
        if not NAME.fullmatch(name) or name in channel_names:
            raise ValueError('channel name')
        channel_names.add(name)
        parts = sequence(channel['parts'],50000)
        budget += len(parts)
        out_parts = []
        for j,part in enumerate(parts):
            exact(part,['case','data'])
            owner = part['case']
            if owner is not None and (type(owner) is not str or owner not in names):
                raise ValueError('owner label')
            out_parts.append({'case':owner,'data':context.template(text(part['data']),f'channel/{index}/part/{j}/data')})
        compiled_channels.append({'name':name,'parts':out_parts})
    if budget>50000 or fields_count>32768:
        raise ValueError('combined budget')
    return cases,actual_test_cases,events,compiled_channels,timeout


def run(document):
    cases,actual_test_cases,events,channels,timeout = compile_document(document)
    fuzzer = FuzzExecutor()
    sent = fuzzer.send_payload(actual_test_cases,events,timeout)
    origin = audit_channels(channels,cases,sent)
    return {'cases':sent,'channels':origin}


def main():
    gc.disable()
    try:
        raw = sys.stdin.buffer.read(8*1024**2+1)
        if len(raw)>8*1024**2:
            raise ValueError('input bytes')
        document = json.loads(raw.decode('utf8'),object_pairs_hook=pairs,
                              parse_constant=bad_constant,parse_float=finite_float)
        result = run(document)
    except (ValueError,TypeError,KeyError,IndexError,UnicodeError,RecursionError):
        result = {'error':'input'}
    encoded=json.dumps(result,ensure_ascii=True,separators=(',',':'),allow_nan=False).encode('ascii')
    sys.stdout.buffer.write(encoded+b'\n')


if __name__=='__main__':main()

import ast
import operator
from pydantic import BaseModel, Field, model_validator, field_validator
from typing import List, Union, Literal, Dict, Optional, Any
import logging
import random
import secrets
import string

logger = logging.getLogger("PayloadEvaluator")

def safe_eval_payload(expr: str, max_length: int = 1024 * 1024 * 5):
    operators = {
        ast.Add: operator.add,
        ast.Mult: operator.mul
    }

    def _eval(node):
        if isinstance(node, ast.Constant):
            return node.value

        elif isinstance(node, ast.BinOp):
            left = _eval(node.left)
            right = _eval(node.right)

            op_type = type(node.op)
            if op_type in operators:
                if op_type == ast.Mult:

                    is_left_str = isinstance(left, str)
                    is_right_str = isinstance(right, str)
                    if is_left_str or is_right_str:

                        target_str = left if is_left_str else right
                        multiplier = right if is_left_str else left

                        if isinstance(target_str, str) and isinstance(multiplier, int):
                            if len(target_str) * multiplier > max_length:
                                raise ValueError(f"Payload result exceeds limit of {max_length} bytes")

                try:
                    return operators[op_type](left, right)
                except Exception as e:
                    raise ValueError(f"Calculation error: {e}")
            else:
                raise ValueError(f"Unsupported operator: {op_type}")

        else:
            raise ValueError(f"Unsupported syntax type: {type(node).__name__}")

    try:
        tree = ast.parse(expr, mode='eval')
        return _eval(tree.body)
    except Exception as e:
        logger.error(f"Failed to evaluate expression '{expr}': {e}")
        return expr


def expand_complex_expression(value: str) -> str:
    if not isinstance(value, str):
        return value

    if "{{" in value and "}}" in value:
        import re
        pattern = r'\{\{(.*?)\}\}'

        def replace_func(match):
            code_snippet = match.group(1).strip()
            try:
                result = safe_eval_payload(code_snippet)
                return str(result)
            except Exception as e:
                return match.group(0)
        return re.sub(pattern, replace_func, value)

    while "<<random_string>>" in value:
        length = random.randint(5, 100)
        chars = string.ascii_letters + string.digits
        rand_str = ''.join(secrets.choice(chars) for _ in range(length))
        value = value.replace("<<random_string>>", rand_str, 1)

    return value


class H3HeaderFrame(BaseModel):
    Type: Literal["headers"] = Field("headers", description="Fixed value, 'headers'")
    headers_kv: Optional[Dict[str, str]] = Field(
        None,
        description="[Recommended] Pass headers using a dictionary format, for example: {':method': 'GET', ':path': '/'}"
    )
    data_to_transfered: Optional[List[List[str]]] = Field(
        None,
        description="Internal field, typically automatically generated by headers_kv. If specified directly, it must be a two-dimensional array [[k,v], ...]"
    )

    End_Stream: bool = Field(False, description="Whether to end the stream after this frame.")

    @model_validator(mode='after')
    def process_headers(self):
        if self.headers_kv:
            self.data_to_transfered = []
            for k, v in self.headers_kv.items():
                expanded_v = expand_complex_expression(str(v))
                self.data_to_transfered.append([k, expanded_v])

        elif self.data_to_transfered:
            new_data = []
            for item in self.data_to_transfered:
                if len(item) == 2:
                    k, v = item
                    expanded_v = expand_complex_expression(str(v))
                    new_data.append([k, expanded_v])
                else:
                    new_data.append(item)
            self.data_to_transfered = new_data

        if self.data_to_transfered is None:
            self.data_to_transfered = []
        return self


class H3DataFrame(BaseModel):
    Type: Literal["data", "datagram"] = Field("data", description="usually 'data'")
    data_to_transfered: str = Field(
        ...,
        description="Raw string content of the payload. Note: Must be a string."
    )

    End_Stream: bool = Field(True, description="Whether to end the stream after this frame.")

    @field_validator('data_to_transfered', mode='before')
    def process_data(cls, v):
        return expand_complex_expression(str(v))


class H3SleepFrame(BaseModel):
    Type: Literal["sleep"] = "sleep"
    Time_to_Stop: int = Field(..., description="Pause duration (milliseconds)")

class FuzzingPayload(BaseModel):
    test_cases: Dict[str, List[Union[H3HeaderFrame, H3DataFrame, H3SleepFrame]]] = Field(
        ...,
        description="A collection of test cases. The key is the test case name (User-Agent), and the value is the list of frames."
    )


def compile_cases(cases, context):
    classes = {'headers': H3HeaderFrame, 'data': H3DataFrame,
               'datagram': H3DataFrame, 'sleep': H3SleepFrame}
    data = {}
    for case in cases:
        data[case['name']] = [classes[frame['Type']].model_validate(frame)
                              for frame in case['frames']]
    return FuzzingPayload.model_construct(test_cases=data)
