"""Byte-sequence API for the compressed payload extension.

Only literal input plumbing is supplied. Complete the operations and Context.
You may replace this representation or reorganize the project.
"""
MAX = (1 << 63) - 1


def literal(data):
    return data


def size(node):
    return len(node) if node is not None else 0


def concat(a, b):
    raise NotImplementedError('compressed sequence concatenation')


def repeat(node, count):
    raise NotImplementedError('compressed sequence repetition')


def cut(node, start, end):
    raise NotImplementedError('compressed byte slices')


def materialize(node, limit=65536):
    if size(node) > limit:
        raise ValueError('bounded materialization')
    return node or b''


def fingerprint(node):
    raise NotImplementedError('exact byte fingerprint')


def next_lf(node, start=0):
    raise NotImplementedError('capture line access')


class Context:
    def __init__(self, definitions, seed):
        self.seed = seed
        self.definitions = definitions
        if definitions:
            raise NotImplementedError('shared byte definitions')

    def expression(self, text):
        raise NotImplementedError('typed compressed expressions')

    def template(self, value, coordinate):
        if type(value) is not str:
            raise ValueError('template type')
        return literal(value.encode('utf8'))
