"""HttpClient request/event core with an injected offline transport and clock.

This is the paired client replay half of the pipeline: it walks compiled fuzz
frames on one virtual connection, retains response events per allocated stream
and fixes the documented lifecycle states (ok / timeout / closed / send_error).
It sends no packets and owns no wall clock; the offline clock supplies time.
"""
from collections import deque
from modules.events import HeadersReceived, DataReceived, ConnectionTerminated, SendError


class HttpClient:
    def __init__(self, clock, backend, timeout_ms):
        self._loop = clock
        self._http = backend
        self._quic = backend
        self._timeout_ms = timeout_ms
        self._request_events = {}
        self._request_waiter = {}
        self._pauses = {}
        self._sending = {}
        self._response_ended = set()
        self._close_info = None

    def _log(self, msg):
        pass

    async def request(self, Case, case_index):
        stream_id = self._quic.get_next_available_stream_id()
        self._request_events[stream_id] = deque()
        self._sending[stream_id] = True
        try:
            for item in Case:
                if self._close_info is not None:
                    raise ConnectionError(self._close_info)
                kind = item['Type']
                if kind == 'sleep':
                    pause = self._loop.sleep(item['Time_to_Stop'], case_index)
                    self._pauses[stream_id] = pause
                    await pause
                    self._pauses.pop(stream_id, None)
                    continue
                if kind == 'headers':
                    self._http.send_headers(stream_id=stream_id,
                                            headers=item['data_to_transfered'],
                                            end_stream=item['End_Stream'])
                elif kind == 'data':
                    self._http.send_data(stream_id=stream_id,
                                         data=item['data_to_transfered'],
                                         end_stream=item['End_Stream'])
                elif kind == 'datagram':
                    self._http.send_datagram(stream_id=stream_id,
                                             data=item['data_to_transfered'])
                else:
                    raise SendError('unsupported frame')
                self.transmit()
            self._sending[stream_id] = False
            if stream_id in self._response_ended:
                # A retained response end completes the case as soon as sending ends.
                return self._finish(stream_id, 'ok')
            waiter = self._loop.create_future()
            self._request_waiter[stream_id] = waiter
            deadline = self._loop.now + self._timeout_ms
            self._loop.schedule(deadline, 2, case_index,
                                lambda sid=stream_id: self._handle_request_timeout(sid))
            await waiter
            return self._finish(stream_id, 'ok')
        except ConnectionError:
            return self._finish(stream_id, 'closed')
        except TimeoutError:
            return self._finish(stream_id, 'timeout')
        except SendError:
            return self._finish(stream_id, 'send_error')

    def _finish(self, stream_id, state):
        events = list(self._request_events.pop(stream_id, ()))
        self._request_waiter.pop(stream_id, None)
        self._pauses.pop(stream_id, None)
        self._sending.pop(stream_id, None)
        return {'state': state, 'at': self._loop.now, 'events': events,
                'stream': stream_id}

    def transmit(self):
        return None

    def _handle_request_timeout(self, stream_id):
        waiter = self._request_waiter.get(stream_id)
        if waiter is not None and not waiter.done():
            self._cancel_request(stream_id, 'Time Out')

    def _cancel_request(self, stream_id, reason):
        waiter = self._request_waiter.get(stream_id)
        if waiter is not None and not waiter.done():
            waiter.set_exception(TimeoutError(reason))

    def http_event_received(self, event):
        stream_id = event.stream_id
        events = self._request_events.get(stream_id)
        if events is None or stream_id in self._response_ended:
            return
        events.append((self._loop.now, event))
        if event.stream_ended:
            self._response_ended.add(stream_id)
            waiter = self._request_waiter.get(stream_id)
            if waiter is not None and not waiter.done() \
                    and not self._sending.get(stream_id, False):
                waiter.set_result(None)

    def quic_event_received(self, event):
        if isinstance(event, ConnectionTerminated):
            if self._close_info is None:
                self._close_info = event.reason_phrase
            for stream_id, waiter in list(self._request_waiter.items()):
                if not waiter.done():
                    waiter.set_exception(ConnectionError(self._close_info))
            for stream_id, pause in list(self._pauses.items()):
                if not pause.done():
                    pause.set_exception(ConnectionError(self._close_info))
        else:
            self.http_event_received(event)

    def connection_lost(self, exc=None):
        self.quic_event_received(ConnectionTerminated(reason_phrase='Connection lost'))
