"""FuzzExecutor frame conversion and execution against an injected transport.

The adapter converts typed compiled payload models into the frame mapping the
client consumes, records every emitted action and accepted response event into
the exact receipt encoding, and produces the client half of the case records.
"""
from HTTP3_Just_Send import HttpClient
from modules.byte_program import (BASE, MASK, Mixer, concat, empty_fingerprint,
                                  fingerprint, literal, size)
from modules.clock import Clock
from modules.events import HeadersReceived, DataReceived, ConnectionTerminated, SendError


def action_pieces(at, stream, kind, data, end=False):
    """Receipt contribution of one emitted action or accepted response event."""
    yield literal(at.to_bytes(8, 'big'))
    yield literal(stream.to_bytes(4, 'big'))
    yield literal(kind.encode('ascii'))
    if kind in ('H', 'h'):
        yield literal(len(data).to_bytes(8, 'big'))
        for name, value in data:
            yield literal(size(name).to_bytes(8, 'big'))
            yield name
            yield literal(size(value).to_bytes(8, 'big'))
            yield value
    else:
        yield literal(size(data).to_bytes(8, 'big'))
        yield data
    yield literal(b'\x01' if end else b'\x00')


def write_action(mixer, at, stream, kind, data, end=False):
    for piece in action_pieces(at, stream, kind, data, end):
        mixer.add(piece)


def encoded_action(at, stream, kind, data, end=False):
    """Whole receipt contribution as one compressed sequence."""
    node = None
    for piece in action_pieces(at, stream, kind, data, end):
        node = piece if node is None else concat(node, piece)
    return node


class OfflineTransport:
    """Records emitted actions and forwards decoded events to the client."""

    def __init__(self, clock, count):
        self.clock = clock
        self.next_stream = 0
        self.ended = set()
        self.count = count
        self.sent = [Mixer() for _ in range(count)]
        self.frames = [0] * count
        self.request_frames = [0] * count
        self.payload_bytes = [0] * count
        self.client = None

    def get_next_available_stream_id(self):
        stream = self.next_stream
        self.next_stream += 4
        return stream

    def record(self, stream_id, kind, data, end_stream=False):
        if stream_id in self.ended:
            raise SendError('frame after request end')
        index = stream_id // 4
        if index >= self.count:
            raise SendError('unknown stream')
        mixer = self.sent[index]
        write_action(mixer, self.clock.now, stream_id, kind, data, end_stream)
        self.frames[index] += 1
        if kind in ('H', 'D'):
            self.request_frames[index] += 1
        if kind == 'H':
            self.payload_bytes[index] += sum(size(n) + size(v) for n, v in data)
        else:
            self.payload_bytes[index] += size(data)
        if end_stream:
            self.ended.add(stream_id)

    def send_headers(self, stream_id, headers, end_stream):
        self.record(stream_id, 'H', headers, end_stream)

    def send_data(self, stream_id, data, end_stream):
        self.record(stream_id, 'D', data, end_stream)

    def send_datagram(self, stream_id, data):
        self.record(stream_id, 'G', data)

    def dispatch(self, record):
        kind = record['kind']
        if kind == 'close':
            self.client.quic_event_received(ConnectionTerminated())
        elif kind == 'headers':
            self.client.quic_event_received(HeadersReceived(
                record['stream'], record['fields'], record['end']))
        elif kind == 'data':
            self.client.quic_event_received(DataReceived(
                record['stream'], record['data'], record['end']))
        else:
            raise ValueError('event kind')


class FuzzExecutor:
    """Compiles payload models into a client replay against the offline clock."""

    def __init__(self, target_ip=None, target_port=None, domain=None):
        self.target_ip = target_ip
        self.target_port = target_port
        self.domain = domain

    def _convert_single_case_frames(self, frames):
        converted_frames = []
        for item in frames:
            new_item = {'Type': item.Type, 'End_Stream': bool(item.End_Stream)}
            if item.Type == 'sleep':
                new_item['Time_to_Stop'] = item.Time_to_Stop
            else:
                new_item['data_to_transfered'] = item.data_to_transfered
            converted_frames.append(new_item)
        return converted_frames

    def send_payload(self, llm_output, records, timeout_ms):
        names = list(llm_output.test_cases)
        clock = Clock()
        transport = OfflineTransport(clock, len(names))
        client = HttpClient(clock, transport, timeout_ms)
        transport.client = client
        coroutines = []
        for index, name in enumerate(names):
            frames = self._convert_single_case_frames(llm_output.test_cases[name])
            coroutines.append(client.request(frames, index))
        results = clock.run(coroutines, records, transport.dispatch)
        out = []
        for index, result in enumerate(results):
            received = Mixer()
            body = Mixer()
            for at, event in result['events']:
                if isinstance(event, HeadersReceived):
                    write_action(received, at, result['stream'], 'h',
                                 event.headers, event.stream_ended)
                else:
                    write_action(received, at, result['stream'], 'd',
                                 event.data, event.stream_ended)
                    body.add(event.data)
            out.append({
                'name': names[index],
                'stream': result['stream'],
                'state': result['state'],
                'at': result['at'],
                'frames': transport.frames[index],
                'request_frames': transport.request_frames[index],
                'payload_bytes': transport.payload_bytes[index],
                'sent': transport.sent[index].result(),
                'received': received.result(),
                'response_frames': len(result['events']),
                'response_body': body.result(),
                'origin_count': 0,
                'flags': [],
            })
        return out
